#include <stdio.h>

struct Cartao {
    int entrada;
    int saida;
};

void cartaoDePonto(int entrada, int saida) {
    struct Cartao c;
    c.entrada = entrada;
    c.saida = saida;
    printf("entrada %d\n", c.entrada);
    printf("saida %d\n", c.saida);
    printf("horas %d\n", c.saida - c.entrada);
}
